unsafe fn lodepng_memcpy(
    mut dst: *mut c_void,
    mut src: *const c_void,
    mut size: size_t,
) {
    let mut i: size_t = 0;
    i = 0 as size_t;
    while i < size {
        *(dst as *mut c_char).offset(i as isize) =
            *(src as *const c_char).offset(i as isize);
        i = i.wrapping_add(1);
    }
}
